def get_pos(cell, size=5):
    return divmod(cell, size)

deltas = [(1,2),(1,-2),(-1,2),(-1,-2),(2,1),(2,-1),(-2,1),(-2,-1)]

def get_neighbors(cell, size=5):
    r, c = get_pos(cell, size)
    neigh = []
    for dr, dc in deltas:
        nr, nc = r + dr, c + dc
        if 0 <= nr < size and 0 <= nc < size:
            neigh.append(nr * size + nc)
    return neigh

adj = {i: get_neighbors(i) for i in range(25)}
print({k: len(v) for k,v in adj.items()})

def is_valid_move(from_cell, to_cell, size=5):
    r1, c1 = divmod(from_cell, size)
    r2, c2 = divmod(to_cell, size)
    dr, dc = abs(r1 - r2), abs(c1 - c2)
    return (dr == 1 and dc == 2) or (dr == 2 and dc == 1)

fixed = {3:23, 4:16, 5:5, 15:15, 22:24}
path = [None] * 25
path[0] = 0
used = set([0])

def backtrack(step):
    if step == 25:
        return True
    if step in fixed:
        cell = fixed[step]
        if cell in used or not is_valid_move(path[step-1], cell):
            return False
        path[step] = cell
        used.add(cell)
        if backtrack(step + 1):
            return True
        used.remove(cell)
        path[step] = None
        return False
    for cell in range(25):
        if cell not in used and is_valid_move(path[step-1], cell):
            path[step] = cell
            used.add(cell)
            if backtrack(step + 1):
                return True
            used.remove(cell)
            path[step] = None
    return False

if backtrack(1):
    print(path)
else:
    print("No solution")
